def test_an_id_that_does_not_resolve_is_caught(rest: FakeRest, mcp: FakeMcp) -> None:
    """A well-shaped id is not evidence, and neither is a correct count delta — the person
    really was created here, just not under the id the tool handed back. Only the lookup
    catches that, and every later step of a use case would key off the wrong id."""
