def test_a_refusal_is_an_error_carrying_the_authored_fragment(rest: FakeRest, mcp: FakeMcp) -> None:
    refused = assert_refusal(
        rest,
        mcp,
        "gramps_delete_person",
        {"gramps_id": "I0002"},
        contains="requires confirm=True",
    )

    assert refused.is_error


def test_a_refusal_with_the_wrong_text_is_caught(rest: FakeRest, mcp: FakeMcp) -> None:
    with pytest.raises(AssertionError, match="not in"):
        assert_refusal(
            rest, mcp, "gramps_delete_person", {"gramps_id": "I0002"}, contains="grade must be >= 1"
        )


def test_a_call_that_succeeds_is_not_a_refusal(rest: FakeRest, mcp: FakeMcp) -> None:
    with pytest.raises(AssertionError, match="did not refuse"):
        assert_refusal(
            rest,
            mcp,
            "gramps_delete_person",
            {"gramps_id": "I0002", "confirm": True},
            contains="requires confirm=True",
        )


def test_a_refusal_that_moved_the_tree_is_caught(rest: FakeRest, mcp: FakeMcp) -> None:
    """A refusal that changed something is the worst outcome of the three, and the only one
    a text assertion alone would call green."""
    mcp.leaky_refusal = True

    with pytest.raises(AssertionError, match="people"):
        assert_refusal(
            rest,
            mcp,
            "gramps_import_file",
            {"filename": "../escape.gramps"},
            contains="Path escapes backup directory",
        )
